// All blocks returned from Notion
const allBlocks = $input.all().map(i => i.json);

// Group blocks by page ID
const grouped = {};

for (const block of allBlocks) {

  const pageId = block.parent?.page_id || block.parent_id;
  if (!pageId) continue;

  if (!grouped[pageId]) grouped[pageId] = [];

  const pushText = (text) => {
    if (text && text.trim()) grouped[pageId].push(text.trim());
  };

  // Handle normal Notion structure
  const richText =
    block.paragraph?.rich_text ||
    block.heading_1?.rich_text ||
    block.heading_2?.rich_text ||
    block.heading_3?.rich_text ||
    block.bulleted_list_item?.rich_text ||
    block.numbered_list_item?.rich_text;

  if (Array.isArray(richText)) {
    pushText(richText.map(t => t.plain_text).join(""));
  }

  // Handle simplified structure
  else if (block.content) {
    pushText(String(block.content));
  }
}

// Convert grouped map into page-level items
const results = Object.entries(grouped).map(([pageId, blocks]) => {

  let fullDescription = blocks.join("\n\n").trim();

  if (fullDescription.length > 12000) {
    fullDescription = fullDescription.slice(0, 12000);
  }

  return {
    json: {
      job_page_id: pageId,
      full_description: fullDescription
    }
  };
});

return results;

