// ======================================
// BACKFILL JOB DESCRIPTION CLEANER
// Place AFTER Merge Node
// ======================================

return items.map(item => {

  // -----------------------------------
  // Detect description field
  // -----------------------------------

  let original =
    item.json.job?.description ||
    item.json.description ||
    item.json.full_description ||
    "";

  let description = original;

  let cleaning_confidence = "high";
  let start_anchor_used = null;
  let end_anchor_used = null;

  // -----------------------------------
  // PHASE 1: NORMALIZATION
  // -----------------------------------

  description = description
    .replace(/\\n/g,"\n")
    .replace(/\/n/g,"\n")
    .replace(/\u00a0/g," ")
    .replace(/\r\n/g,"\n")
    .replace(/\t/g," ")
    .replace(/ +/g," ")
    .replace(/\n{3,}/g,"\n\n")
    .trim();

  // remove urls
  description = description.replace(/https?:\/\/\S+/g,"");

  // safer line merge
  description = description.replace(/([a-z])\n([A-Z])/g,"$1 $2");


  // ======================================
  // REQUIREMENT SECTION EXTRACTOR
  // ======================================

  const sections = [

    "requirements",
    "qualifications",
    "skills and experience",
    "what you'll need",
    "what you will need",
    "what we are looking for",
    "minimum qualifications",
    "preferred qualifications",

    "responsibilities",
    "key responsibilities",
    "key accountabilities",
    "duties"

  ];

  let lower = description.toLowerCase();

  let matches = [];

  for (const marker of sections) {

    const idx = lower.indexOf(marker);

    if (idx !== -1) {

      matches.push({
        marker,
        index: idx
      });

    }

  }

  matches.sort((a,b)=>a.index-b.index);

  // -----------------------------------
  // Prefer requirement sections
  // -----------------------------------

  const requirementMarkers = [
    "requirements",
    "qualifications",
    "skills and experience",
    "minimum qualifications",
    "preferred qualifications"
  ];

  const requirementMatches =
    matches.filter(m =>
      requirementMarkers.includes(m.marker)
    );

  if (requirementMatches.length > 0) {
    matches = requirementMatches;
  }

  let extractedSections = [];

  for (let i = 0; i < matches.length; i++) {

    const start = matches[i].index;

    const end =
      matches[i+1]?.index ||
      description.length;

    extractedSections.push(
      description.slice(start,end)
    );

  }

  let cleaned = extractedSections.join("\n\n");

  if (cleaned.length >= 300) {
    description = cleaned;
  }

  lower = description.toLowerCase();


  // -----------------------------------
  // PHASE 2: START ANCHOR
  // -----------------------------------

  const startAnchors = [

    "requirements",
    "qualifications",
    "skills and experience",
    "minimum qualifications",
    "preferred qualifications",

    "responsibilities",
    "key responsibilities",
    "key accountabilities",

    "what you'll need",
    "what you will need",
    "what we are looking for",

    "about the role",
    "role summary"

  ];

  let startIndex = -1;

  const searchLimit =
    Math.floor(description.length * 0.40);

  for (const marker of startAnchors){

    const idx = lower.indexOf(marker);

    if(idx !== -1 && idx < searchLimit){

      startIndex = idx;
      start_anchor_used = marker;
      break;

    }

  }

  let sliced = description;

  if(startIndex !== -1){

    sliced = description.slice(startIndex);

  } else {

    cleaning_confidence = "low";

  }

  // -----------------------------------
  // PHASE 3: OPTIONAL END ANCHOR
  // -----------------------------------

  const endAnchors = [

    "about us",
    "company overview",
    "equal opportunity employer",
    "diversity and inclusion",
    "benefits",
    "privacy policy",
    "legal disclaimer",
    "job posting end date"

  ];

  const slicedLower = sliced.toLowerCase();

  let endIndex = -1;

  for (const marker of endAnchors) {

    const idx = slicedLower.indexOf(marker);

    if (idx !== -1 && idx > 600 &&
        idx < sliced.length * 0.9) {

      endIndex = idx;
      end_anchor_used = marker;
      break;

    }

  }

  if (endIndex !== -1) {

    sliced = sliced.slice(0, endIndex);

  }

  // -----------------------------------
  // PHASE 4: VALIDATION
  // -----------------------------------

  if(sliced.length < 400){

    sliced = original;
    cleaning_confidence = "fallback_length";

  }

  const bulletPattern =
    /[-–—•*●○]\s|\d+\.\s|\d+\)/;

  const hasBullet =
    bulletPattern.test(sliced);

  const hasSentence =
    sliced
      .split(".")
      .some(s => s.trim().length > 20);

  if(!hasBullet || !hasSentence){

    sliced = original;
    cleaning_confidence = "fallback_structure";

  }

  // -----------------------------------
  // OUTPUT
  // -----------------------------------

  return {

    json: {

      ...item.json,

      safe_description: sliced,

      cleaning_meta: {

        start_anchor_used,
        end_anchor_used,

        extracted_sections:
          matches.map(m => m.marker),

        original_length: original.length,
        cleaned_length: sliced.length,

        cleaning_ratio:
          original.length
            ? (sliced.length / original.length).toFixed(2)
            : null,

        confidence: cleaning_confidence

      }

    }

  };

});

// ======================================
// OLLAMA JSON PARSER
// Run Once For All Items
// ======================================

const output = [];

for (const item of items) {

  const raw =
    item.json.message?.content ||
    item.json.response ||
    "";

  let parsed;

  try {

    parsed = JSON.parse(raw);

  } catch (e) {

    const start = raw.indexOf("{");
    const end = raw.lastIndexOf("}");

    if (start !== -1 && end !== -1) {

      try {
        parsed = JSON.parse(raw.slice(start,end+1));
      } catch(err) {
        parsed = null;
      }

    }

  }

  if (!parsed) {

    output.push({
      json:{
        ...item.json,
        parse_error: true
      }
    });

    continue;

  }

  output.push({
    json:{
      ...item.json,
      structured_requirements: parsed
    }
  });

}

return output;

// ====================================
// REQUIREMENT CLEANER
// Run Once For All Items
// ====================================

const SOFT_SKILLS = [

"communication",
"teamwork",
"collaboration",
"stakeholder",
"interpersonal",
"fast paced",
"self starter",
"motivated",
"detail oriented",
"multitask",
"problem solving",
"leadership",
"presentation"

];

const TECH_SIGNALS = [

"risk","control","framework","policy","compliance",
"security","iam","identity","access","cloud",
"incident","threat","vulnerability","audit",
"governance","nist","iso","soc","gdpr",
"rbac","azure","aws","gcp"

];

function isSoftSkill(text){

  const lower = text.toLowerCase();

  return SOFT_SKILLS.some(s => lower.includes(s));

}

function hasTechSignal(text){

  const lower = text.toLowerCase();

  return TECH_SIGNALS.some(k => lower.includes(k));

}

function scoreRequirement(text){

  const lower = text.toLowerCase();

  let score = 0;

  TECH_SIGNALS.forEach(k=>{
    if(lower.includes(k)) score += 2;
  });

  if(text.length > 100) score += 1;

  return score;

}

return items.map(item => {

  const structured = item.json.structured_requirements;

  if(!structured) return item;

  let must = structured.must_have || [];
  let nice = structured.nice_to_have || [];

  // remove soft skills
  must = must.filter(r => !isSoftSkill(r));
  nice = nice.filter(r => !isSoftSkill(r));

  // require technical signal
  must = must.filter(hasTechSignal);
  nice = nice.filter(hasTechSignal);

  // ranking
  must = must
    .map(r=>({text:r,score:scoreRequirement(r)}))
    .sort((a,b)=>b.score-a.score)
    .slice(0,6)
    .map(r=>r.text);

  nice = nice
    .map(r=>({text:r,score:scoreRequirement(r)}))
    .sort((a,b)=>b.score-a.score)
    .slice(0,4)
    .map(r=>r.text);

  return {

    json:{
      ...item.json,

      structured_requirements:{
        ...structured,
        must_have: must,
        nice_to_have: nice
      }

    }

  };

});

// ========================================
// NOTION PAYLOAD BUILDER
// Run Once Per Item
// ========================================

const req = $json.structured_requirements;

if (!req || !req.role_title || !Array.isArray(req.must_have)) {
  throw new Error("Invalid LLM structure");
}

const now = new Date();

// ---- stringify JSON for storage ----
const content = JSON.stringify(req, null, 2);

// ---- Extract experience safely ----
const minYears = typeof req.experience?.min_years === "number"
  ? req.experience.min_years
  : null;

const seniority = typeof req.experience?.seniority_level === "string"
  ? req.experience.seniority_level
  : "unknown";

const cluster = typeof req.role_cluster_hint === "string"
  ? req.role_cluster_hint
  : null;

// ---- Chunk JSON for Notion (2000 char limit) ----
const maxChunkSize = 1950;
const chunks = [];

for (let i = 0; i < content.length; i += maxChunkSize) {
  chunks.push({
    type: "text",
    text: {
      content: content.slice(i, i + maxChunkSize)
    }
  });
}

// ---- Build Notion payload ----
const notion_payload = {

  properties: {

    structured_requirements: {
      rich_text: chunks
    },

    extractor_run_time: {
      date: {
        start: now.toISOString()
      }
    },

    job_minimum_years: {
      number: minYears
    },

    job_cluster: cluster
      ? { select: { name: cluster } }
      : { select: null },

    job_seniority: {
      rich_text: [
        {
          type: "text",
          text: { content: seniority }
        }
      ]
    },

    extractor_version: {
      rich_text: [
        {
          type: "text",
          text: { content: "Backfill.V.0.2" }
        }
      ]
    }

  }

};

// ---- Return single item ----
return {
  json: {
    job_page_id: $json.job_page_id,
    notion_payload
  }
};
